{
  "API_calls": [],
  "collected_information": {
    "environment_setup": {
      "from_README.md": {
        "install_stable": "python -m pip install gpt-engineer",
        "install_dev": [
          "git clone https://github.com/AntonOsika/gpt-engineer.git",
          "cd gpt-engineer",
          "python -m pip install -e ."
        ],
        "alternative_dev_install": "make install && source venv/bin/activate",
        "set_openai_api_key": "export OPENAI_API_KEY or copy .env.template to .env",
        "run_project": "gpt-engineer projects/my-new-project"
      }
    },
    "dependencies_and_test_framework": {
      "python_version": ">=3.8, <4.0",
      "key_dependencies": {
        "black": "23.3.0",
        "click": ">= 8.0.0",
        "mypy": "1.3.0",
        "openai": "0.27.8",
        "pre-commit": "3.3.3",
        "pytest": "7.3.1",
        "ruff": "0.0.272",
        "termcolor": "2.3.0",
        "typer": ">= 0.3.2",
        "rudder-sdk-python": "2.0.2",
        "dataclasses-json": "0.5.7",
        "tiktoken": ">= 0.0.4",
        "tabulate": "0.9.0",
        "python-dotenv": ">= 0.21.0",
        "langchain": ">= 0.0.240"
      },
      "testing_framework": "pytest 7.3.1"
    },
    "ci_test_command": "pytest --cov=gpt_engineer",
    "tests_directory": {
      "missing_file": "tests/test_azure_openai.py not found",
      "existing_files": [
        "tests/test_ai.py",
        "tests/test_collect.py",
        "tests/test_db.py",
        "tests/test_chat_to_files.py"
      ],
      "subfolders": [
        "tests/steps/"
      ]
    },
    "notes": {
      "env_var_openai_api_key": "Must be set for running project or tests requiring it",
      "run_tests": "pytest or pytest --cov=gpt_engineer",
      "no_specific_instructions_for_missing_test_file": true
    }
  },
  "terminate": true
}
